@Test
public void testReadingFromFile() throws IOException {
    NamespacePrefixProvider provider = new NamespacePrefixProviderImpl(new FileInputStream(mappingFile));
    //this tests the namespaces defined in namespaceprefix.mappings file
    Assert.assertEquals("http://www.example.org/test#", provider.getNamespace("test"));
    Assert.assertEquals("http://www.example.org/test-1/", provider.getNamespace("test-1"));
    Assert.assertEquals("urn:example.text:", provider.getNamespace("urn_test"));
    List<String> prefixes = provider.getPrefixes("http://www.example.org/test#");
    Assert.assertEquals(2, prefixes.size());
    Assert.assertEquals("test", prefixes.get(0));
    Assert.assertEquals("test2", prefixes.get(1));
    Assert.assertEquals("http://www.example.org/test#", provider.getNamespace("test"));
    Assert.assertEquals("http://www.example.org/test#", provider.getNamespace("test2"));
}

@Test
public void testReadingFromMap() {
    Map<String, String> mappings = new LinkedHashMap<String, String>();
    mappings.put("test", "http://www.example.org/test#");
    mappings.put("test-1", "http://www.example.org/test-1/");
    mappings.put("urn_test", "urn:example.text:");
    mappings.put("test2", "http://www.example.org/test#");
    //add some invalid mappings
    mappings.put("test:3", "http://www.example.org/test#");
    mappings.put("test3", "http://www.example.org/test");
    NamespacePrefixProvider provider = new NamespacePrefixProviderImpl(mappings);
    //this tests the namespaces defined in namespaceprefix.mappings file
    Assert.assertEquals("http://www.example.org/test#", provider.getNamespace("test"));
    Assert.assertEquals("http://www.example.org/test-1/", provider.getNamespace("test-1"));
    Assert.assertEquals("urn:example.text:", provider.getNamespace("urn_test"));
    List<String> prefixes = provider.getPrefixes("http://www.example.org/test#");
    Assert.assertEquals(2, prefixes.size());
    Assert.assertEquals("test", prefixes.get(0));
    Assert.assertEquals("test2", prefixes.get(1));
    Assert.assertEquals("http://www.example.org/test#", provider.getNamespace("test"));
    Assert.assertEquals("http://www.example.org/test#", provider.getNamespace("test2"));
    //test that illegal mappings are not imported
    Assert.assertNull(provider.getNamespace("test:3"));
    Assert.assertNull(provider.getNamespace("test3"));
}

@Test
public void testPrefixCheck() {
    Assert.assertTrue(NamespaceMappingUtils.checkPrefix(""));
    Assert.assertTrue(NamespaceMappingUtils.checkPrefix("12"));
    Assert.assertTrue(NamespaceMappingUtils.checkPrefix("ab"));
    Assert.assertTrue(NamespaceMappingUtils.checkPrefix("AB"));
    Assert.assertTrue(NamespaceMappingUtils.checkPrefix("a1B"));
    Assert.assertTrue(NamespaceMappingUtils.checkPrefix("a-b"));
    Assert.assertTrue(NamespaceMappingUtils.checkPrefix("a_b"));
    Assert.assertFalse(NamespaceMappingUtils.checkPrefix("a#"));
    Assert.assertFalse(NamespaceMappingUtils.checkPrefix("a/"));
    Assert.assertFalse(NamespaceMappingUtils.checkPrefix("a:"));
    Assert.assertFalse(NamespaceMappingUtils.checkPrefix(" a"));
    Assert.assertFalse(NamespaceMappingUtils.checkPrefix("a "));
    Assert.assertFalse(NamespaceMappingUtils.checkPrefix("å"));
    Assert.assertFalse(NamespaceMappingUtils.checkPrefix("?"));
}

@Test
public void testNamespaceCheck() {
    Assert.assertTrue(NamespaceMappingUtils.checkNamespace("http://www.example.com/"));
    Assert.assertFalse(NamespaceMappingUtils.checkNamespace("http://www.example.com"));
    Assert.assertTrue(NamespaceMappingUtils.checkNamespace("http://www.example.com/test/"));
    Assert.assertFalse(NamespaceMappingUtils.checkNamespace("http://www.example.com/test"));
    Assert.assertTrue(NamespaceMappingUtils.checkNamespace("http://www.example.com/test#"));
    //for uris no ':'
    Assert.assertFalse(NamespaceMappingUtils.checkNamespace("http://www.example.com/test:"));
    //for urn's only : is allowd
    Assert.assertTrue(NamespaceMappingUtils.checkNamespace("urn:example.text:"));
    Assert.assertFalse(NamespaceMappingUtils.checkNamespace("urn:example.text"));
    Assert.assertFalse(NamespaceMappingUtils.checkNamespace("urn:example.text/"));
    Assert.assertFalse(NamespaceMappingUtils.checkNamespace("urn:example.text#"));
    //no relative URI namespaces
    Assert.assertFalse(NamespaceMappingUtils.checkNamespace("test/example/"));
    Assert.assertFalse(NamespaceMappingUtils.checkNamespace("test/example#"));
    Assert.assertFalse(NamespaceMappingUtils.checkNamespace("test/example:"));
    Assert.assertFalse(NamespaceMappingUtils.checkNamespace("test/example:test/"));
}

@Test
public void testGetNamespace() {
    Assert.assertEquals("http://www.example.com/test#", NamespaceMappingUtils.getNamespace("http://www.example.com/test#"));
    Assert.assertEquals("http://www.example.com/test#", NamespaceMappingUtils.getNamespace("http://www.example.com/test#localname"));
    Assert.assertEquals("http://www.example.com/test/", NamespaceMappingUtils.getNamespace("http://www.example.com/test/localname"));
    Assert.assertEquals("http://www.example.com/test/", NamespaceMappingUtils.getNamespace("http://www.example.com/test/"));
    Assert.assertEquals("http://www.example.com/", NamespaceMappingUtils.getNamespace("http://www.example.com/test:localname"));
    Assert.assertEquals("http://www.example.com/", NamespaceMappingUtils.getNamespace("http://www.example.com/test?param=test&param1=test"));
    Assert.assertNull(NamespaceMappingUtils.getNamespace("http://www.example.com"));
    Assert.assertEquals("urn:example:", NamespaceMappingUtils.getNamespace("urn:example:"));
    Assert.assertEquals("urn:example:", NamespaceMappingUtils.getNamespace("urn:example:localname"));
    Assert.assertEquals("urn:example:", NamespaceMappingUtils.getNamespace("urn:example:localname/other"));
    Assert.assertEquals("urn:example:", NamespaceMappingUtils.getNamespace("urn:example:localname#other"));
}

