@Test
public void testConversionMethods() {
    Assert.assertEquals("http://www.example.org/test#localname", service.getFullName("test:localname"));
    Assert.assertEquals("http://www.example.org/test#localname:test", service.getFullName("test:localname:test"));
    Assert.assertEquals("http://www.example.org/test#localname", service.getFullName("http://www.example.org/test#localname"));
    Assert.assertEquals("urn:example.text:localname", service.getFullName("urn_test:localname"));
    Assert.assertEquals("urn:example.text:localname/test", service.getFullName("urn_test:localname/test"));
    Assert.assertEquals("urn:example.text:localname", service.getFullName("urn:example.text:localname"));
    Assert.assertNull(service.getFullName("nonExistentPrefix:localname"));
}

