    // {lang1} or {lang2} are expected to look like:
    //
    //    select ?entity, ?label where {
    //        ?entity rdfs:label ?label
    //        FILTER((regex(str(?label),"\\b{text1}\\b","i") || regex(str(?label),"\\b{text2}\\b","i"))
