@Test
public void testFieldQueryValueConstraints() throws IOException, JSONException {
    FieldQueryTestCase test = new FieldQueryTestCase("{ " + "'selected': [" + "'http:\\/\\/www.w3.org\\/2000\\/01\\/rdf-schema#label']," + "'offset': '0'," + "'limit': '5'," + "'constraints': [{ " + "'type': 'value'," + "'value': '64'," + "'field': 'http:\\/\\/www.w3.org\\/2003\\/01\\/geo\\/wgs84_pos#alt'," + "'datatype': 'xsd:int'" + "}]" + "}", //list of expected results
    Arrays.//list of expected results
    asList("http://dbpedia.org/resource/Manchester,_New_Hampshire", "http://dbpedia.org/resource/Cornwall,_Ontario", "http://dbpedia.org/resource/Lexington,_Massachusetts"), //list of required fields for results
    Arrays.//list of required fields for results
    asList("http://www.w3.org/2000/01/rdf-schema#label"));
    //now execute the test
    executeQuery(test);
    // now the same query but with no datatype
    test = new FieldQueryTestCase("{ " + "'selected': [" + "'http:\\/\\/www.w3.org\\/2000\\/01\\/rdf-schema#label']," + "'offset': '0'," + "'limit': '3'," + "'constraints': [{ " + "'type': 'value'," + //NOTE this is a JSON String!
    "'value': '64'," + "'field': 'http:\\/\\/www.w3.org\\/2003\\/01\\/geo\\/wgs84_pos#alt'," + "}]" + "}", //we expect no results, because the datatype should be xsd:string
    false);
