/**
 * We test here all acceptable return types
 */
@Test
public void testOutputFormats() throws Exception {
    log.info("testOutputFormats()");
    final String[] formats = { // Each group of 3 elements is: Accept header, Expected content-type,
    // Expected regexp
    "text/html", "text/html", ".*Reasoners: Result.*", "application/rdf+xml", "application/rdf+xml", "rdf:RDF", /* FIXME This is not supported by the OWLApi JAX-RS writer
                                  "text/n3",
                                  "text/n3",
                                  "<.*www.w3.org/2000/01/rdf-schema.*>",
*/
    "application/turtle", "application/turtle", "<.*www.w3.org/2000/01/rdf-schema.*>" /* FIXME This is not supported by the OWLApi JAX-RS writer
                                  "text/plain",
                                  "text/plain",
                                  "<.*www.w3.org/2000/01/rdf-schema.*>"
*/
    };
    List<String> sl = allServices();
    for (String s : sl) {
        for (String t : TASKS) {
            String url = REASONERS_PATH + s + t;
            for (int i = 0; i < formats.length; i += 3) {
                executor.execute(buildMultipartRequest(url, multiPart).withHeader("Accept", formats[i])).assertStatus(200).assertContentType(formats[i + 1]);
                // Only if task is not CHECK
                if (t.equals("/check")) {
                    // FIXME
                    // Check should not support these formats or it should return something compatible
                    // Now returns the sentence
                    executor.assertContentContains("The input is consistent");
                } else {
                    executor.assertContentRegexp(formats[i + 2]);
                }
                log.info("Service {} supports return type {}", url, formats[i]);
            }
        }
    }
}

