        if (kReSKB != null) {
            RuleList kReSRuleList = kReSKB.getRuleList();
            if (kReSRuleList != null) {
                for (Rule kReSRule : kReSRuleList) {
                    log.debug("RULE : " + kReSRule.toString());
                }
            }
            log.debug("RULE LIST IS NULL");
        } else {
            log.debug("KB IS NULL");
        }
    } catch (Exception e) {
        e.printStackTrace();
    }
}

